00112 void OutputBitstream::write   ( uint32_t uiBits, uint32_t uiNumberOfBits )
00113 {
00114   CHECK( uiNumberOfBits > 32, "Number of bits is exceeds '32'" );
00115   CHECK( uiNumberOfBits != 32 && (uiBits & (~0 << uiNumberOfBits)) != 0, "Unsupported parameters" );
00116 
00117   /* any modulo 8 remainder of num_total_bits cannot be written this time,
00118    * and will be held until next time. */
00119   uint32_t num_total_bits = uiNumberOfBits + m_num_held_bits;
00120   uint32_t next_num_held_bits = num_total_bits % 8;
00121 
00122   /* form a byte aligned word (write_bits), by concatenating any held bits
00123    * with the new bits, discarding the bits that will form the next_held_bits.
00124    * eg: H = held bits, V = n new bits        /---- next_held_bits
00125    * len(H)=7, len(V)=1: ... ---- HHHH HHHV . 0000 0000, next_num_held_bits=0
00126    * len(H)=7, len(V)=2: ... ---- HHHH HHHV . V000 0000, next_num_held_bits=1
00127    * if total_bits < 8, the value of v_ is not used */
00128   uint8_t next_held_bits = uiBits << (8 - next_num_held_bits);
00129 
00130   if (!(num_total_bits >> 3))
00131   {
00132     /* insufficient bits accumulated to write out, append new_held_bits to
00133      * current held_bits */
00134     /* NB, this requires that v only contains 0 in bit positions {31..n} */
00135     m_held_bits |= next_held_bits;
00136     m_num_held_bits = next_num_held_bits;
00137     return;
00138   }
00139 
00140   /* topword serves to justify held_bits to align with the msb of uiBits */
00141   uint32_t topword = (uiNumberOfBits - next_num_held_bits) & ~((1 << 3) -1);
00142   uint32_t write_bits = (m_held_bits << topword) | (uiBits >> next_num_held_bits);
00143 
00144   switch (num_total_bits >> 3)
00145   {
00146   case 4: m_fifo.push_back(write_bits >> 24);
00147   case 3: m_fifo.push_back(write_bits >> 16);
00148   case 2: m_fifo.push_back(write_bits >> 8);
00149   case 1: m_fifo.push_back(write_bits);
00150   }
00151 
00152   m_held_bits = next_held_bits;
00153   m_num_held_bits = next_num_held_bits;
00154 }
00155 
00156 void OutputBitstream::writeAlignOne()
00157 {
00158   uint32_t num_bits = getNumBitsUntilByteAligned();
00159   write((1 << num_bits) - 1, num_bits);
00160   return;
00161 }
00162 
00163 void OutputBitstream::writeAlignZero()
00164 {
00165   if (0 == m_num_held_bits)
00166   {
00167     return;
00168   }
00169   m_fifo.push_back(m_held_bits);
00170   m_held_bits = 0;
00171   m_num_held_bits = 0;
00172 }
00173 
00179 void   OutputBitstream::addSubstream( OutputBitstream* pcSubstream )
00180 {
00181   uint32_t uiNumBits = pcSubstream->getNumberOfWrittenBits();
00182 
00183   const vector<uint8_t>& rbsp = pcSubstream->getFIFO();
00184   for (vector<uint8_t>::const_iterator it = rbsp.begin(); it != rbsp.end();)
00185   {
00186     write(*it++, 8);
00187   }
00188   if (uiNumBits&0x7)
00189   {
00190     write(pcSubstream->getHeldBits()>>(8-(uiNumBits&0x7)), uiNumBits&0x7);
00191   }
00192 }
00193 
00194 void OutputBitstream::writeByteAlignment()
00195 {
00196   write( 1, 1);
00197   writeAlignZero();
00198 }
