00200 int OutputBitstream::countStartCodeEmulations()
00201 {
00202   uint32_t cnt = 0;
00203   vector<uint8_t>& rbsp   = getFIFO();
00204   for (vector<uint8_t>::iterator it = rbsp.begin(); it != rbsp.end();)
00205   {
00206     vector<uint8_t>::iterator found = it;
00207     do
00208     {
00209       // find the next emulated 00 00 {00,01,02,03}
00210       // NB, end()-1, prevents finding a trailing two byte sequence
00211       found = search_n(found, rbsp.end()-1, 2, 0);
00212       found++;
00213       // if not found, found == end, otherwise found = second zero byte
00214       if (found == rbsp.end())
00215       {
00216         break;
00217       }
00218       if (*(++found) <= 3)
00219       {
00220         break;
00221       }
00222     } while (true);
00223     it = found;
00224     if (found != rbsp.end())
00225     {
00226       cnt++;
00227     }
00228   }
00229   return cnt;
00230 }
