00240 void InputBitstream::pseudoRead ( uint32_t uiNumberOfBits, uint32_t& ruiBits )
00241 {
00242   uint32_t saved_num_held_bits = m_num_held_bits;
00243   uint8_t saved_held_bits = m_held_bits;
00244   uint32_t saved_fifo_idx = m_fifo_idx;
00245 
00246   uint32_t num_bits_to_read = min(uiNumberOfBits, getNumBitsLeft());
00247   read(num_bits_to_read, ruiBits);
00248   ruiBits <<= (uiNumberOfBits - num_bits_to_read);
00249 
00250   m_fifo_idx = saved_fifo_idx;
00251   m_held_bits = saved_held_bits;
00252   m_num_held_bits = saved_num_held_bits;
00253 }
00254 
00255 
00256 void InputBitstream::read (uint32_t uiNumberOfBits, uint32_t& ruiBits)
00257 {
00258   CHECK( uiNumberOfBits > 32, "Too many bits read" );
00259 
00260   m_numBitsRead += uiNumberOfBits;
00261 
00262   /* NB, bits are extracted from the MSB of each byte. */
00263   uint32_t retval = 0;
00264   if (uiNumberOfBits <= m_num_held_bits)
00265   {
00266     /* n=1, len(H)=7:   -VHH HHHH, shift_down=6, mask=0xfe
00267      * n=3, len(H)=7:   -VVV HHHH, shift_down=4, mask=0xf8
00268      */
00269     retval = m_held_bits >> (m_num_held_bits - uiNumberOfBits);
00270     retval &= ~(0xff << uiNumberOfBits);
00271     m_num_held_bits -= uiNumberOfBits;
00272     ruiBits = retval;
00273     return;
00274   }
00275 
00276   /* all num_held_bits will go into retval
00277    *   => need to mask leftover bits from previous extractions
00278    *   => align retval with top of extracted word */
00279   /* n=5, len(H)=3: ---- -VVV, mask=0x07, shift_up=5-3=2,
00280    * n=9, len(H)=3: ---- -VVV, mask=0x07, shift_up=9-3=6 */
00281   uiNumberOfBits -= m_num_held_bits;
00282   retval = m_held_bits & ~(0xff << m_num_held_bits);
00283   retval <<= uiNumberOfBits;
00284 
00285   /* number of whole bytes that need to be loaded to form retval */
00286   /* n=32, len(H)=0, load 4bytes, shift_down=0
00287    * n=32, len(H)=1, load 4bytes, shift_down=1
00288    * n=31, len(H)=1, load 4bytes, shift_down=1+1
00289    * n=8,  len(H)=0, load 1byte,  shift_down=0
00290    * n=8,  len(H)=3, load 1byte,  shift_down=3
00291    * n=5,  len(H)=1, load 1byte,  shift_down=1+3
00292    */
00293   uint32_t aligned_word = 0;
00294   uint32_t num_bytes_to_load = (uiNumberOfBits - 1) >> 3;
00295   CHECK(m_fifo_idx + num_bytes_to_load >= m_fifo.size(), "Exceeded FIFO size");
00296 
00297   switch (num_bytes_to_load)
00298   {
00299   case 3: aligned_word  = m_fifo[m_fifo_idx++] << 24;
00300   case 2: aligned_word |= m_fifo[m_fifo_idx++] << 16;
00301   case 1: aligned_word |= m_fifo[m_fifo_idx++] <<  8;
00302   case 0: aligned_word |= m_fifo[m_fifo_idx++];
00303   }
00304 
00305   /* resolve remainder bits */
00306   uint32_t next_num_held_bits = (32 - uiNumberOfBits) % 8;
00307 
00308   /* copy required part of aligned_word into retval */
00309   retval |= aligned_word >> next_num_held_bits;
00310 
00311   /* store held bits */
00312   m_num_held_bits = next_num_held_bits;
00313   m_held_bits = aligned_word;
00314 
00315   ruiBits = retval;
00316 }
