00322 void OutputBitstream::insertAt(const OutputBitstream& src, uint32_t pos)
00323 {
00324   CHECK(0 != src.getNumberOfWrittenBits() % 8, "Number of written bits is not a multiple of 8");
00325 
00326   vector<uint8_t>::iterator at = m_fifo.begin() + pos;
00327   m_fifo.insert(at, src.m_fifo.begin(), src.m_fifo.end());
00328 }
00329 
00330 uint32_t InputBitstream::readOutTrailingBits ()
00331 {
00332   uint32_t count=0;
00333   uint32_t uiBits = 0;
00334 
00335   while ( ( getNumBitsLeft() > 0 ) && (getNumBitsUntilByteAligned()!=0) )
00336   {
00337     count++;
00338     read ( 1, uiBits );
00339   }
00340   return count;
00341 }
