00359 InputBitstream *InputBitstream::extractSubstream( uint32_t uiNumBits )
00360 {
00361   uint32_t uiNumBytes = uiNumBits/8;
00362   InputBitstream *pResult = new InputBitstream;
00363 
00364   std::vector<uint8_t> &buf = pResult->getFifo();
00365   buf.reserve((uiNumBits+7)>>3);
00366 
00367   if (m_num_held_bits == 0)
00368   {
00369     std::size_t currentOutputBufferSize=buf.size();
00370     const uint32_t uiNumBytesToReadFromFifo = std::min<uint32_t>(uiNumBytes, (uint32_t)m_fifo.size() - m_fifo_idx);
00371     buf.resize(currentOutputBufferSize+uiNumBytes);
00372     memcpy(&(buf[currentOutputBufferSize]), &(m_fifo[m_fifo_idx]), uiNumBytesToReadFromFifo); m_fifo_idx+=uiNumBytesToReadFromFifo;
00373     if (uiNumBytesToReadFromFifo != uiNumBytes)
00374     {
00375       memset(&(buf[currentOutputBufferSize+uiNumBytesToReadFromFifo]), 0, uiNumBytes - uiNumBytesToReadFromFifo);
00376     }
00377   }
00378   else
00379   {
00380     for (uint32_t ui = 0; ui < uiNumBytes; ui++)
00381     {
00382       uint32_t uiByte;
00383       read(8, uiByte);
00384       buf.push_back(uiByte);
00385     }
00386   }
00387   if (uiNumBits&0x7)
00388   {
00389     uint32_t uiByte = 0;
00390     read(uiNumBits&0x7, uiByte);
00391     uiByte <<= 8-(uiNumBits&0x7);
00392     buf.push_back(uiByte);
00393   }
00394   return pResult;
00395 }
00396 
00397 uint32_t InputBitstream::readByteAlignment()
00398 {
00399   uint32_t code = 0;
00400   read( 1, code );
00401   CHECK(code != 1, "Code is not '1'");
00402 
00403   uint32_t numBits = getNumBitsUntilByteAligned();
00404   if(numBits)
00405   {
00406     CHECK(numBits > getNumBitsLeft(), "More bits available than left");
00407     read( numBits, code );
00408     CHECK(code != 0, "Code not '0'");
00409   }
00410   return numBits+1;
00411 }
